export function test(): string {
  let ns: number[] = [1.5, 2.5];
  ns[1] = ns[0] + 1.0;
  let ss: string[] = ["a", "b"];
  ss[0] = ss[1] + "x";
  let bs: boolean[] = [true, false];
  bs[1] = bs[0];
  if (ns[0] === 1.5 && ns[1] === 2.5 && ss[0] === "bx" && ss[1] === "b" && bs[0] && bs[1] && ns.length === 2 && ss.length === 2 && bs.length === 2) {
    return "ok";
  }
  return "bad";
}

function fill(xs: int[], v: int): int[] {
  xs[0] = v;
  xs[1] = v + 1;
  return xs;
}
function total(xs: int[]): int { return xs[0] + xs[1]; }
export function test(): int {
  let xs: int[] = [0, 0];
  let ys: int[] = fill(xs, 10);
  return total(ys) + xs.length;
}

